/// `SVC_A1`.
///
/// Cut: BRANCH, ConditionPassed.
pub(super) fn SVC_A1(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::SVC_A1;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    st.cond_guard(b, ((w >> 28) & 0xf));
    st.svc(b, None);
    Ok(())
}

